+            Response other = (Response) o;
+            return Objects.equals(runDuration, other.runDuration)
+                && Objects.equals(timeBetweenStarts, other.timeBetweenStarts)
+                && Objects.equals(dataStreamStats, other.dataStreamStats);
+        }
