+                builder.startObject();
+                builder.field("name", stat.dataStreamName);
+                builder.field("backing_indices_in_total", stat.backingIndicesInTotal);
+                builder.field("backing_indices_in_error", stat.backingIndicesInError);
+                builder.endObject();
+                return builder;
+            }), Iterators.single((builder, params) -> {
+                builder.endArray();
+                builder.endObject();
+                return builder;
+            }));
